package ru.mtproxy.picker;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.Color;import android.widget.*;import android.view.*;import android.text.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Personal collection, independent of public list and preserving unknown proxies. */
public final class ManualActivity extends Activity {
 final ArrayList<ManualEntry> entries=new ArrayList<>(),removed=new ArrayList<>();final ExecutorService worker=Executors.newSingleThreadExecutor();LinearLayout rows;TextView status,counts;EditText search;Spinner filter,sort;Button add,check,cleanup,undo;ProgressBar progress;boolean busy,dead;int visible=60;CancellableOperation operation;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(Color.WHITE);return v;}
 Button action(String label,Runnable run){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(0xff343434);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffffb44d));b.setOnClickListener(v->{if(!busy)run.run();});return b;}
 void pair(LinearLayout page,View a,View b){LinearLayout row=new LinearLayout(this);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.rightMargin=dp(8);row.addView(a,lp);row.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));page.addView(row);}
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff343434);root.setPadding(dp(16),dp(16),dp(16),dp(16));root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(16),dp(12)+i.getSystemWindowInsetTop(),dp(16),dp(12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);root.addView(UiKit.homeButton(this,()->finish()));root.addView(text("Манул · мои прокси",24));counts=text("",12);root.addView(counts);
 add=action("Добавить / импорт",()->addMenu());check=action("Проверить",()->probeAll());pair(root,add,check);cleanup=action("Удалить мёртвые",()->removeDead());cleanup.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffff987e));root.addView(cleanup,new LinearLayout.LayoutParams(-1,dp(44)));
 search=new EditText(this);search.setSingleLine(true);search.setHint("Поиск: адрес, порт, WEB / MTProto");search.setTextSize(14);search.setTextColor(Color.WHITE);search.setHintTextColor(0xffc5c5c5);root.addView(search);filter=spinner(new String[]{"Все","Живые","Мёртвые","Не проверены"});sort=spinner(new String[]{"По пингу","По адресу"});pair(root,filter,sort);
 status=text("",12);root.addView(status);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setVisibility(View.GONE);root.addView(progress);undo=action("Отменить удаление",()->{int n=merge(new ArrayList<>(removed));removed.clear();save();render();status.setText("Восстановлено: "+n);});undo.setVisibility(View.GONE);root.addView(undo);
 ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));load();
 search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){visible=60;render();}public void afterTextChanged(Editable e){}});AdapterView.OnItemSelectedListener listener=new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){visible=60;render();}};filter.setOnItemSelectedListener(listener);sort.setOnItemSelectedListener(listener);render();}
 Spinner spinner(String[] values){Spinner v=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,values);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);v.setAdapter(adapter);return v;}
 void load(){try{JSONArray saved=new JSONArray(getSharedPreferences("manual",0).getString("entries","[]"));for(int i=0;i<saved.length();i++){JSONObject row=saved.getJSONObject(i);List<ManualEntry> parsed=ManualEntry.parse(row.getString("link"));if(!parsed.isEmpty()){ManualEntry e=parsed.get(0);e.ms=row.optLong("ms",-2);entries.add(e);}}}catch(Exception ignored){}}
 void save(){try{JSONArray data=new JSONArray();for(ManualEntry e:entries)data.put(new JSONObject().put("link",e.link).put("ms",e.ms));getSharedPreferences("manual",0).edit().putString("entries",data.toString()).apply();}catch(Exception ignored){}}
 int merge(List<ManualEntry> next){Set<String> known=new HashSet<>();for(ManualEntry e:entries)known.add(e.link);int added=0;for(ManualEntry e:next)if(entries.size()<3000&&known.add(e.link)){entries.add(e);added++;}return added;}
 void addMenu(){new AlertDialog.Builder(this).setTitle("Работа со списком").setItems(new String[]{"Вставить ссылки","Импорт из «Халявы»","Получить списки из источников","Скопировать весь список"},(d,index)->{if(index==0)editor();if(index==1){List<ManualEntry> parsed=ManualEntry.parse(getSharedPreferences("MainActivity",0).getString("list",""));int n=merge(parsed);save();render();status.setText(parsed.isEmpty()?"Сначала получите список в «Халяве»":"Добавлено: "+n);}if(index==2)importSources();if(index==3){StringBuilder data=new StringBuilder();for(ManualEntry e:entries)data.append(e.link).append('\n');copy(data.toString());}}).setNegativeButton("Закрыть",null).show();}
 void editor(){EditText input=new EditText(this);input.setHint("tg://proxy, t.me/proxy или t.me/webproxy\nМожно вставить целый список");input.setMinLines(3);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Добавить прокси").setView(input).setNegativeButton("Отмена",null).setPositiveButton("Добавить",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{List<ManualEntry> parsed=ManualEntry.parse(input.getText().toString());if(parsed.isEmpty()){input.setError("Не найдены корректные ссылки");return;}int n=merge(parsed);save();render();status.setText("Добавлено: "+n);dialog.dismiss();}));dialog.show();}
 void copy(String value){if(value.isEmpty()){status.setText("Список пуст");return;}((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Мои прокси",value));status.setText("Скопировано");}
 void removeDead(){removed.clear();for(Iterator<ManualEntry> it=entries.iterator();it.hasNext();){ManualEntry e=it.next();if(ManualLists.dead(e)){removed.add(e);it.remove();}}save();render();status.setText("Удалено мёртвых: "+removed.size()+". Непроверенные сохранены.");}
 void state(boolean value){busy=value;progress.setVisibility(value?View.VISIBLE:View.GONE);render();}
 void importSources(){boolean[] selected=new boolean[MainActivity.SOURCE_NAMES.length];for(int i=0;i<selected.length;i++)selected[i]=getSharedPreferences("MainActivity",0).getBoolean("source_"+i,i==0);new AlertDialog.Builder(this).setTitle("Источники").setMultiChoiceItems(MainActivity.SOURCE_NAMES,selected,(d,i,c)->selected[i]=c).setNegativeButton("Отмена",null).setPositiveButton("Получить",(d,w)->{int count=0;for(boolean b:selected)if(b)count++;if(count==0){status.setText("Выберите источник");return;}final int total=count;state(true);progress.setIndeterminate(false);progress.setMax(total);progress.setProgress(0);status.setText("Загрузка…");final CancellableOperation run=new CancellableOperation();operation=run;run.track(worker.submit(()->{ArrayList<ManualEntry> result=new ArrayList<>();ArrayList<String> failed=new ArrayList<>();int done=0;for(int i=0;i<selected.length&&!dead;i++)if(selected[i]){try{List<ManualEntry> parsed=ManualEntry.parse(MainActivity.download(MainActivity.SOURCE_URLS[i],run));if(parsed.isEmpty())throw new Exception();result.addAll(parsed);}catch(Exception e){failed.add(MainActivity.SOURCE_NAMES[i]);}final int n=++done;runOnUiThread(()->{if(!dead){progress.setProgress(n);status.setText("Источники: "+n+" / "+total);}});}runOnUiThread(()->{if(dead)return;int n=merge(result);save();operation=null;state(false);status.setText("Добавлено: "+n+(failed.isEmpty()?"":". Не загрузились: "+android.text.TextUtils.join(", ",failed)));});}));}).show();}
 void probeAll(){if(entries.isEmpty())return;state(true);status.setText("Проверено 0 / "+entries.size());progress.setIndeterminate(false);progress.setMax(entries.size());progress.setProgress(0);final ArrayList<ManualEntry> batch=new ArrayList<>(entries);final CancellableOperation run=new CancellableOperation();operation=run;run.track(worker.submit(()->{ProbeEngine.refreshDns();ExecutorService pool=Executors.newFixedThreadPool(16);ArrayList<Future<Long>> results=new ArrayList<>();long[] values=new long[batch.size()];try{for(ManualEntry e:batch){Future<Long> future=pool.submit(()->ProbeEngine.measure(e.host,e.port,1500));run.track(future);results.add(future);}for(int i=0;i<results.size()&&!dead;i++){values[i]=-1;try{values[i]=results.get(i).get();}catch(Exception ignored){}final int n=i+1;if(n%8==0||n==batch.size())runOnUiThread(()->{if(!dead){progress.setProgress(n);status.setText("Проверено "+n+" / "+batch.size());}});}}finally{pool.shutdownNow();}runOnUiThread(()->{if(dead||run.isCancelled())return;for(int i=0;i<batch.size();i++)batch.get(i).ms=values[i];save();operation=null;state(false);status.setText("Готово. WEB: измерен только TCP 443.");});}));}
 void render(){if(rows==null)return;rows.removeAllViews();int live=0,deadCount=0,unknown=0;for(ManualEntry e:entries){if(e.ms>=0)live++;else if(ManualLists.dead(e))deadCount++;else unknown++;}counts.setText("Всего "+entries.size()+" · живых "+live+" · мёртвых "+deadCount+" · без проверки "+unknown);add.setEnabled(!busy);check.setEnabled(!busy&&!entries.isEmpty());cleanup.setEnabled(!busy&&deadCount>0);cleanup.setText("Удалить мёртвые · "+deadCount);undo.setVisibility(removed.isEmpty()?View.GONE:View.VISIBLE);undo.setEnabled(!busy);undo.setText("Отменить удаление · "+removed.size());ArrayList<ManualEntry> found=new ArrayList<>();for(ManualEntry e:ManualLists.sorted(entries,sort.getSelectedItemPosition()))if(ManualLists.matches(e,search.getText().toString(),filter.getSelectedItemPosition()))found.add(e);if(found.isEmpty())rows.addView(text(entries.isEmpty()?"Пока пусто. Нажмите «Добавить / импорт».":"Нет совпадений. Измените поиск или фильтр.",15));int count=Math.min(visible,found.size());for(int i=0;i<count;i++){ManualEntry e=found.get(i);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackgroundColor(0xff454545);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(8);rows.addView(card,cp);card.addView(text(e.host+":"+e.port+(e.web?" · WEB":" · MTProto"),16));TextView rating=text(PingQuality.label(e.ms)+(e.ms>=0?" · "+e.ms+" мс":""),13);rating.setTextColor(PingQuality.color(e.ms));card.addView(rating);Button connect=action("Подключить",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(e.link)));}catch(ActivityNotFoundException ex){status.setText("Установите Telegram");}});Button menu=action("Ещё ⋮",()->{PopupMenu popup=new PopupMenu(this,card);popup.getMenu().add("Скопировать ссылку");popup.getMenu().add("Удалить");popup.setOnMenuItemClickListener(item->{if(busy)return false;if(item.getTitle().equals("Удалить")){removed.clear();removed.add(e);entries.remove(e);save();render();}else copy(e.link);return true;});popup.show();});connect.setEnabled(!busy);menu.setEnabled(!busy);pair(card,connect,menu);}if(count<found.size())rows.addView(action("Показать ещё · "+(found.size()-count),()->{visible+=60;render();}));}
 @Override protected void onDestroy(){dead=true;if(operation!=null)operation.cancel();worker.shutdownNow();super.onDestroy();}
}
